// CORRECCIÓN: NTAG215 entrega UID de 7 bytes = 14 hex. La regla antigua (16–32)
// los descartaba en silencio. Aceptamos 8–20 hex y los campos uid o epc.
const body = $input.first().json.body || $input.first().json;
const vistos = new Set(); const eventos = [];
for (const l of (body.lecturas || [])) {
  const uid = String(l.uid || l.epc || '').trim().toUpperCase().replace(/[\s:-]/g,'');
  if (!/^[0-9A-F]{8,20}$/.test(uid)) continue;
  if (vistos.has(uid)) continue;
  vistos.add(uid);
  eventos.push({ uid, obra_id: body.obra_id || 'OBRA-001', lector_id: body.lector_id || 'LECTOR-1',
    zona: body.zona || 'bodega', direccion: (body.direccion === 'salida') ? 'salida' : 'entrada',
    rssi: l.rssi ?? null, ts: l.ts || new Date().toISOString() });
}
if (!eventos.length) return [{ json: { sin_lecturas_validas: true } }];
return eventos.map(e => ({ json: e }));

const ev = $('A1 · Verificar credencial del lector').first().json;
const num = v => { const n = parseFloat(String(v ?? '').replace(',','.')); return isNaN(n)?0:n; };
const limpio = s => String(s ?? '').trim().toUpperCase().replace(/[\s:-]/g,'');
const mat = $input.all().map(i=>i.json).find(m => limpio(m.uid_tag) === ev.uid);
if (!mat || !mat.material_id)
  return [{ json: { valido:false, respuesta:{ ok:false, error:'uid_desconocido', uid:ev.uid } } }];
const previo = num(mat.stock);
const delta = ev.direccion === 'salida' ? -1 : 1;
const nuevo = Math.max(0, previo + delta);
const minimo = num(mat.minimo);
const critico = minimo > 0 && nuevo < minimo;
const severidad = critico ? 'critica' : (minimo>0 && nuevo < minimo*1.25 ? 'advertencia' : 'ok');
return [{ json: {
  valido:true, critico, material_id:mat.material_id, nombre:mat.nombre, stock:nuevo,
  mov_id:'MOV-'+Date.now()+'-'+Math.floor(Math.random()*1000),
  ts:ev.ts, uid_tag:ev.uid, direccion:ev.direccion, delta, stock_resultante:nuevo,
  lector_id:ev.lector_id, obra_id:ev.obra_id,
  respuesta:{ ok:true, uid:ev.uid, nombre:mat.nombre, direccion:ev.direccion, stock:nuevo, minimo, severidad }
} }];

// Toma el archivo más recientemente modificado de la carpeta de programación.
const archivos = $input.all().map(i => i.json).filter(a => a.id);
if (!archivos.length) return [{ json: { sin_programacion: true } }];
archivos.sort((a,b) => new Date(b.modifiedTime||0) - new Date(a.modifiedTime||0));
const a = archivos[0];
return [{ json: { file_id: a.id, file_name: a.name, mimeType: a.mimeType, modifiedTime: a.modifiedTime } }];

// Reúne: programación de obra (Drive) + stock (Inventario) + consumo real (Movimientos).
const num = v => { const n = parseFloat(String(v ?? '').replace(',','.')); return isNaN(n)?0:n; };
const hoy = new Date();
const iso = d => d.toISOString().slice(0,10);

let programacion = [];
try { programacion = $('A2 · Leer programación (CSV)').all().map(i=>i.json).filter(r=>Object.keys(r).length); } catch(e) {}
let archivo = 'sin archivo';
try { archivo = $('A2 · Elegir archivo más reciente').first().json.file_name || 'sin archivo'; } catch(e) {}

const inventario = $('A2 · Leer inventario').all().map(i=>i.json).filter(m=>m.material_id);
const movimientos = $('A2 · Leer movimientos').all().map(i=>i.json).filter(m=>m.material_id);

const desde = new Date(hoy.getTime() - 14*864e5);
const consumo = {};
for (const m of movimientos) {
  const t = new Date(m.ts);
  if (isNaN(t) || t < desde) continue;
  const d = num(m.delta);
  if (d < 0) consumo[m.material_id] = (consumo[m.material_id] || 0) + Math.abs(d);
}

const materiales = inventario.map(m => {
  const total14 = consumo[m.material_id] || 0;
  const diario = +(total14 / 14).toFixed(3);
  const stock = num(m.stock);
  const dias = diario > 0 ? Math.floor(stock / diario) : null;
  return { material_id:m.material_id, nombre:m.nombre, categoria:m.categoria, unidad:m.unidad,
    stock, minimo:num(m.minimo), maximo:num(m.maximo), proveedor:m.proveedor,
    consumo_14d: total14, consumo_diario: diario,
    dias_para_quiebre_lineal: dias,
    fecha_quiebre_lineal: dias === null ? null : iso(new Date(hoy.getTime() + dias*864e5)) };
});

return [{ json: { fecha: iso(hoy), obra_id: 'OBRA-001', archivo_programacion: archivo,
  programacion: programacion.slice(0, 60), materiales } }];

