// Parsea el array de la IA. Si falla, usa la proyección lineal como respaldo:
// la demo nunca se queda sin predicciones.
const ctx = $('A2 · Consolidar contexto').first().json;
let preds = null;
try {
  const bruto = String($input.first().json.output ?? $input.first().json.text ?? '').replace(/```json|```/g,'').trim();
  const arr = JSON.parse(bruto.slice(bruto.indexOf('['), bruto.lastIndexOf(']')+1));
  if (Array.isArray(arr) && arr.length) preds = arr;
} catch(e) {}

if (!preds) {
  preds = ctx.materiales
    .filter(m => m.consumo_diario > 0 || m.stock < m.minimo)
    .map(m => {
      const d = m.dias_para_quiebre_lineal ?? 0;
      return { material_id:m.material_id, nombre:m.nombre, consumo_diario:m.consumo_diario,
        dias_para_quiebre:d, fecha_quiebre:m.fecha_quiebre_lineal,
        urgencia: (m.stock < m.minimo || d <= 7) ? 'alta' : (d <= 14 ? 'media' : 'baja'),
        partida_afectada:'sin partida asociada',
        razonamiento:'Proyección lineal sobre consumo RFID de los últimos 14 días.' };
    });
}

const stock = Object.fromEntries(ctx.materiales.map(m => [m.material_id, m.stock]));
const filas = preds.map(p => ({
  prediccion_id: p.material_id + '-' + ctx.fecha,
  fecha: ctx.fecha,
  material_id: p.material_id,
  nombre: p.nombre,
  stock: stock[p.material_id] ?? 0,
  consumo_diario: p.consumo_diario ?? 0,
  dias_para_quiebre: p.dias_para_quiebre ?? 0,
  fecha_quiebre: p.fecha_quiebre ?? '',
  urgencia: p.urgencia ?? 'media',
  partida_afectada: p.partida_afectada ?? 'sin partida asociada',
  razonamiento: p.razonamiento ?? ''
}));
return filas.map(f => ({ json: f }));

// Materiales que requieren acción hoy y aún no fueron avisados.
const num = v => { const n = parseFloat(String(v ?? '').replace(',','.')); return isNaN(n)?0:n; };
const hoy = new Date().toISOString().slice(0,10);
const inv = $('A3 · Leer inventario').all().map(i=>i.json).filter(m=>m.material_id);
const preds = $('A3 · Leer predicciones').all().map(i=>i.json).filter(p=>p.material_id && String(p.fecha)===hoy);
const alertas = $input.all().map(i=>i.json).filter(a=>a.alerta_id);
const cuerpo = $('A3 · Webhook acción').first().json.body || {};

const yaAvisado = new Set(alertas.filter(a => String(a.fecha)===hoy &&
  String(a.correo_enviado).toLowerCase()==='si').map(a => String(a.material_id)));
const predPorMat = Object.fromEntries(preds.map(p => [p.material_id, p]));

const objetivo = inv.filter(m => {
  const bajoMinimo = num(m.minimo) > 0 && num(m.stock) < num(m.minimo);
  const p = predPorMat[m.material_id];
  const quiebreProximo = p && String(p.urgencia).toLowerCase() === 'alta';
  return bajoMinimo || quiebreProximo;
}).filter(m => !yaAvisado.has(String(m.material_id)));

if (!objetivo.length) return [{ json: { hay_accion: false, fecha: hoy, mensaje: 'Sin materiales nuevos que accionar hoy.' } }];

const items = objetivo.map(m => {
  const p = predPorMat[m.material_id] || {};
  const cantidad = Math.max(1, num(m.maximo) - num(m.stock));
  return { material_id:m.material_id, nombre:m.nombre, categoria:m.categoria, unidad:m.unidad || 'un',
    stock:num(m.stock), minimo:num(m.minimo), maximo:num(m.maximo),
    proveedor:m.proveedor || 'sin proveedor declarado',
    precio_ref:num(m.precio_ref), cantidad_sugerida:cantidad, costo_estimado:cantidad*num(m.precio_ref),
    bajo_minimo: num(m.minimo)>0 && num(m.stock)<num(m.minimo),
    dias_para_quiebre: p.dias_para_quiebre ?? null, urgencia_prediccion: p.urgencia ?? null,
    partida_afectada: p.partida_afectada ?? 'sin partida asociada' };
});
return [{ json: { hay_accion:true, fecha:hoy, obra_id: cuerpo.obra_id || 'OBRA-001',
  disparador: cuerpo.disparador || 'manual', items } }];

