// Extrae el JSON de la IA. Respaldo determinístico si falla: la demo no se cae.
const d = $('A3 · Detectar qué accionar').first().json;
const clp = n => '$' + Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g,'.');
let j = null;
try {
  const b = String($input.first().json.output ?? $input.first().json.text ?? '').replace(/```json|```/g,'').trim();
  j = JSON.parse(b.slice(b.indexOf('{'), b.lastIndexOf('}')+1));
} catch(e) {}

if (!j || !j.asunto || !j.cuerpo_html) {
  const filas = d.items.map(c => `<tr><td>${c.nombre}</td><td align="center">${c.stock} ${c.unidad}</td><td align="center">${c.minimo}</td><td align="center">${c.dias_para_quiebre ?? '—'}</td><td align="center"><b>${c.cantidad_sugerida} ${c.unidad}</b></td><td>${c.proveedor}</td><td align="right">${clp(c.costo_estimado)}</td></tr>`).join('');
  j = {
    asunto: `STOK · ${d.obra_id}: ${d.items.length} material(es) requieren compra`,
    cuerpo_html: `<p>Estimado equipo,</p><p>La captura RFID y la proyección contra la programación de obra detectaron los siguientes materiales en riesgo en ${d.obra_id} (${d.fecha}):</p><table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-family:Arial;font-size:13px"><tr style="background:#0F1B3D;color:#fff"><th>Material</th><th>Stock</th><th>Mínimo</th><th>Días para quiebre</th><th>Cantidad sugerida</th><th>Proveedor</th><th>Costo estimado</th></tr>${filas}</table><p><b>Recomendación:</b> emitir la orden de compra hoy para no detener las partidas.</p><p>— Agente de acción STOK</p>`,
    mensaje_pantalla: `${d.items.length} material(es) requieren compra inmediata.`,
    recomendaciones: d.items.map(c => ({ material_id:c.material_id, cantidad_sugerida:c.cantidad_sugerida,
      motivo:`Stock ${c.stock} ${c.unidad} bajo mínimo ${c.minimo}. Partida: ${c.partida_afectada}.`,
      prioridad: (c.bajo_minimo || (c.dias_para_quiebre !== null && c.dias_para_quiebre <= 7)) ? 'alta' : 'media' }))
  };
}
const porId = Object.fromEntries(d.items.map(i => [i.material_id, i]));
const recs = (j.recomendaciones || []).map(r => {
  const it = porId[r.material_id] || {};
  const cant = Number(r.cantidad_sugerida) || it.cantidad_sugerida || 1;
  return { rec_id: r.material_id + '-' + d.fecha, fecha: d.fecha, material_id: r.material_id,
    nombre: it.nombre || r.material_id, cantidad_sugerida: cant, unidad: it.unidad || 'un',
    proveedor: it.proveedor || '', costo_estimado: cant * (it.precio_ref || 0),
    motivo: r.motivo || '', prioridad: r.prioridad || 'media', estado: 'pendiente' };
});
return [{ json: { asunto:j.asunto, cuerpo_html:j.cuerpo_html,
  mensaje_pantalla: j.mensaje_pantalla || `${d.items.length} material(es) requieren compra.`,
  fecha:d.fecha, obra_id:d.obra_id, items:d.items, recomendaciones:recs,
  total_estimado: recs.reduce((s,r)=>s+r.costo_estimado,0) } }];

const d = $('A3 · Parsear (con respaldo)').first().json;
return d.items.map(c => ({ json: {
  alerta_id: c.material_id + '-' + d.fecha, fecha: d.fecha, material_id: c.material_id, nombre: c.nombre,
  stock: c.stock, minimo: c.minimo, cantidad_sugerida: c.cantidad_sugerida,
  proveedor: c.proveedor, correo_enviado: 'si', mensaje: d.mensaje_pantalla } }));

const num = v => { const n = parseFloat(String(v ?? '').replace(',', '.')); return isNaN(n) ? 0 : n; };
const hoy = new Date().toISOString().slice(0, 10);

const resp = $input.first().json;
const ranges = resp.valueRanges || [];

// Convierte un value range (array de arrays) en array de objetos usando la primera fila como headers
const toObjects = (vr) => {
  if (!vr || !vr.values || !vr.values.length) return [];
  const [headers, ...rows] = vr.values;
  return rows.map(row => {
    const obj = {};
    headers.forEach((h, i) => { obj[h] = row[i] ?? ''; });
    return obj;
  });
};

// El orden coincide con el orden de "ranges" pedido en el nodo HTTP Request:
// Inventario, Movimientos, Predicciones, Recomendaciones, Alertas, Lectores
const [invRaw, movRaw, predRaw, recRaw, alertRaw, lectRaw] = ranges.map(toObjects);

const materiales = (invRaw || []).filter(m => m.material_id).map(m => ({
  material_id: m.material_id, nombre: m.nombre, categoria: m.categoria || '', zona: m.zona || 'bodega',
  unidad: m.unidad || 'un', stock: num(m.stock), minimo: num(m.minimo), maximo: num(m.maximo),
  proveedor: m.proveedor || '', precio_ref: num(m.precio_ref),
  tag_registrado: /^[0-9A-F]{8,20}$/i.test(String(m.uid_tag || '').trim())
}));

const movimientos = (movRaw || []).filter(m => m.mov_id)
  .sort((a, b) => new Date(b.ts) - new Date(a.ts)).slice(0, 40)
  .map(m => ({ ts: m.ts, nombre: m.nombre, direccion: m.direccion, delta: num(m.delta), stock: num(m.stock_resultante), lector: m.lector_id }));

const predicciones = (predRaw || []).filter(p => p.material_id && String(p.fecha) === hoy)
  .map(p => ({
    material_id: p.material_id, nombre: p.nombre, consumo_diario: num(p.consumo_diario),
    dias_para_quiebre: num(p.dias_para_quiebre), fecha_quiebre: p.fecha_quiebre,
    urgencia: String(p.urgencia || 'media').toLowerCase(), partida: p.partida_afectada, razonamiento: p.razonamiento
  }))
  .sort((a, b) => a.dias_para_quiebre - b.dias_para_quiebre);

const recomendaciones = (recRaw || []).filter(r => r.rec_id)
  .filter(r => String(r.estado || 'pendiente').toLowerCase() !== 'descartada')
  .map(r => ({
    rec_id: r.rec_id, fecha: r.fecha, material_id: r.material_id, nombre: r.nombre,
    cantidad_sugerida: num(r.cantidad_sugerida), unidad: r.unidad, proveedor: r.proveedor,
    costo_estimado: num(r.costo_estimado), motivo: r.motivo,
    prioridad: String(r.prioridad || 'media').toLowerCase(), estado: String(r.estado || 'pendiente').toLowerCase()
  }))
  .sort((a, b) => (a.prioridad === 'alta' ? 0 : 1) - (b.prioridad === 'alta' ? 0 : 1));

const alertas = (alertRaw || []).filter(a => a.alerta_id)
  .sort((a, b) => String(b.fecha).localeCompare(String(a.fecha))).slice(0, 20)
  .map(a => ({
    alerta_id: a.alerta_id, fecha: a.fecha, nombre: a.nombre, stock: num(a.stock), minimo: num(a.minimo),
    mensaje: a.mensaje || `${a.nombre} bajo el mínimo (${num(a.stock)}/${num(a.minimo)}).`,
    correo_enviado: String(a.correo_enviado || '').toLowerCase() === 'si', del_dia: String(a.fecha) === hoy
  }));

const lectores = (lectRaw || []).filter(l => l.lector_id).map(l => ({
  lector_id: l.lector_id, obra_id: l.obra_id, zona: l.zona || 'bodega',
  activo: String(l.activo || '').trim().toLowerCase() === 'si',
  ultimo_latido: l.ultimo_latido || null, descripcion: l.descripcion || '',
  vinculado: !!String(l.token || '').trim()
}));

const ultimoMov = movimientos[0] ? movimientos[0].ts : null;
const q = $('API · GET dashboard').first().json.query || {};

return [{
  json: {
    obra_id: q.obra_id || 'OBRA-001', actualizado: new Date().toISOString(), fecha: hoy,
    materiales, movimientos, predicciones, recomendaciones, alertas, lectores,
    agentes: {
      captura: { activo: !!ultimoMov, ultimo: ultimoMov, lectores: lectores.filter(l => l.activo).length },
      prediccion: { activo: predicciones.length > 0, ultimo: predicciones.length ? hoy : null, total: predicciones.length },
      accion: { activo: recomendaciones.length > 0, ultimo: recomendaciones[0] ? recomendaciones[0].fecha : null, pendientes: recomendaciones.filter(r => r.estado === 'pendiente').length }
    }
  }
}];

const body = $input.first().json.body || $input.first().json;
const items = Array.isArray(body.inventario) ? body.inventario : [];
return items.filter(m=>m.material_id).map(m => ({ json: {
  material_id: m.material_id, minimo: Number(m.minimo)||0, maximo: Number(m.maximo)||0,
  proveedor: m.proveedor ?? '' } }));

// CAMINO CORTO · autenticación del lector.
// Cada ESP32 lleva un token. Se compara contra la pestaña Lectores antes de tocar el stock.
// El obra_id NO se toma del payload: se toma de la fila del lector. Así un lector nunca
// puede escribir en la bodega de otra obra, aunque el firmware venga mal configurado.
// LA DIRECCIÓN (entrada/salida) TAMPOCO se toma del payload: manda la columna "modo"
// de la fila del lector. Así configuras el sentido físico del portal desde la planilla,
// sin depender de que el firmware del ESP32 lo mande bien.
const ev = $('A1 · Validar UID (NTAG215)').first().json;
if (ev.sin_lecturas_validas)
  return [{ json: { autorizado:false, respuesta:{ ok:false, error:'sin_lecturas_validas' } } }];

const req = $('A1 · Webhook lectura RFID').first().json;
const headers = req.headers || {};
const body = req.body || {};
// El token viaja en el header Authorization: Bearer <token>, o en el cuerpo como respaldo.
const bruto = String(headers.authorization || headers.Authorization || body.token || '');
const token = bruto.replace(/^Bearer\s+/i, '').trim();

if (!token)
  return [{ json: { autorizado:false, respuesta:{ ok:false, error:'sin_token', mensaje:'El lector no envió credencial.' } } }];

const lectores = $input.all().map(i => i.json).filter(l => l.lector_id);
const fila = lectores.find(l => String(l.token || '').trim() === token);

if (!fila)
  return [{ json: { autorizado:false, respuesta:{ ok:false, error:'token_invalido', mensaje:'Lector no reconocido en esta obra.' } } }];
if (String(fila.activo || '').trim().toLowerCase() !== 'si')
  return [{ json: { autorizado:false, respuesta:{ ok:false, error:'lector_desactivado', lector_id: fila.lector_id } } }];

// La dirección la decide la planilla (columna "modo"). Si viene vacía o con un valor
// no reconocido, se respeta lo que haya calculado A1 · Validar UID como respaldo.
const modo = String(fila.modo || '').trim().toLowerCase();
const direccion = (modo === 'salida' || modo === 'entrada') ? modo : ev.direccion;

return [{ json: { ...ev, autorizado:true,
  lector_id: fila.lector_id,
  obra_id: fila.obra_id,               // manda la planilla, no el firmware
  zona: fila.zona || ev.zona,
  direccion,                           // manda la planilla ("modo"), no el firmware
  ultimo_latido: new Date().toISOString() } }];

const d = $input.first().json;

return [{
  json: {
    ok: true,
    hay_accion: true,
    mensaje: d.mensaje_pantalla || 'Compras revisadas correctamente.',
    recomendaciones: Array.isArray(d.recomendaciones) ? d.recomendaciones.length : 0,
    total_estimado: d.total_estimado || 0,
    fecha: new Date().toISOString()
  }
}];

const d = $input.first().json;

return [{
  json: {
    ok: true,
    hay_accion: false,
    mensaje: d.mensaje || 'Sin materiales nuevos que accionar hoy.',
    fecha: new Date().toISOString()
  }
}];
